// Authentic schema 5 saves from the v0.22.0 release (tests/fixtures/pot-0.22.0.json,
// regenerated by tests/fixtures/generate-0.22.0.js from tag v0.22.0, a5e74ba).
// Each pot was played twice from the same seed and inputs, with Auto Steam on
// and off, so the only difference is the mode 0.23.0 migrates it to.
import { describe, expect, it } from 'vitest';
import release from '../fixtures/pot-0.22.0.json' with { type: 'json' };
import { POT_SCHEMA_VERSION, migrateCheckpoint, validateCheckpoint } from '../../src/core/checkpoint.js';
import { createGame } from '../../src/core/game.js';
import { createSessions } from '../../src/core/sessions.js';
import { milkCapacity, passiveMilkGain, sugarCapacity } from '../../src/gameplay/weapons.js';
import { POT_KEY, createLocalProgress } from '../../src/storage/localProgress.js';
import { continueFrom, leave, killLast, omit } from '../support/legacyPlay.js';

const POTS = [
  ['earlyAuto', 'chill', true], ['earlyManual', 'arcade', false],
  ['chapter2Auto', 'chill', true], ['chapter2Manual', 'arcade', false],
];

function memoryStorage(entries = {}) {
  const map = new Map(Object.entries(entries));
  return { getItem: (k) => map.get(k) ?? null, setItem: (k, v) => map.set(k, String(v)), removeItem: (k) => map.delete(k) };
}

describe('authentic v0.22.0 (schema 5) saved pots', () => {
  it('are genuine 0.22.0 schema 5 saves, identical apart from Auto Steam', () => {
    expect(release).toMatchObject({ version: '0.22.0', commit: 'a5e74bab4e777d3812ad4cefd158e861f518c386' });
    for (const stage of ['early', 'chapter2']) {
      const auto = release.checkpoints[`${stage}Auto`], manual = release.checkpoints[`${stage}Manual`];
      for (const cp of [auto, manual]) {
        expect(cp.schemaVersion).toBe(5);
        expect(Object.hasOwn(cp.state, 'mode')).toBe(false);
        expect(cp.state.phase).toBe('reading');
        expect(cp.state.tray).toBeNull(); // nothing waits to be served, so the next cup's supplies follow from the rules alone
      }
      expect([auto.state.autoSteam, manual.state.autoSteam]).toEqual([true, false]);
      expect(omit(auto.state, ['autoSteam'])).toEqual(omit(manual.state, ['autoSteam']));
      expect(auto.random).toEqual(manual.random);
    }
    // Sugar beyond 0.23.0's capacity (2, plus one per Sugar Scoop), from 0.22.0's per-round refills and bonuses.
    expect(release.checkpoints.earlyAuto.state).toMatchObject({ round: 2, milkLeft: 1, sugarLeft: 3 });
    expect(release.checkpoints.chapter2Auto.state).toMatchObject({ round: 8, milkLeft: 1, sugarLeft: 4,
      progress: { chapter: 2 }, spoon: { sugarScoop: 1 } });
    expect(release.checkpoints.chapter2Auto.state.porcelain.fractures.length).toBeGreaterThan(0);
  });

  for (const [name, mode, autoSteam] of POTS) {
    describe(`${name} (Auto Steam ${autoSteam ? 'on' : 'off'})`, () => {
      const saved = release.checkpoints[name];

      it(`migrates to ${mode} with every other piece of state and every random stream intact`, () => {
        const input = structuredClone(saved);
        const migrated = migrateCheckpoint(input);
        expect(input).toEqual(saved); // the caller's copy is never changed
        expect(migrated.schemaVersion).toBe(POT_SCHEMA_VERSION);
        expect(validateCheckpoint(migrated)).toBe(true);
        expect(migrated.state.mode).toBe(mode);
        expect(migrated.state.autoSteam).toBe(autoSteam);
        // Score, round, Heat, chapters, upgrades, cash, cup damage, inventory, the pending reading: all as saved.
        expect(omit(migrated.state, ['mode'])).toEqual(saved.state);
        expect(migrated.random).toEqual(saved.random);
        expect(migrated.pinnedTea).toEqual(saved.pinnedTea);
      });

      it('restores at the saved reading, keeping legacy inventory until the next cup clamps it', () => {
        const game = createGame({ checkpoint: structuredClone(saved) });
        const s = game.state;
        expect(s).toMatchObject({ phase: 'reading', mode, round: saved.state.round, score: saved.state.score,
          teaCash: saved.state.teaCash, milkLeft: saved.state.milkLeft, sugarLeft: saved.state.sugarLeft, offer: saved.state.offer });
        expect(s.sugarLeft).toBeGreaterThan(sugarCapacity(s));
        const carried = { milk: s.milkLeft, sugar: s.sugarLeft };
        leave(game);
        expect(s).toMatchObject({ phase: 'playing', round: saved.state.round + 1 });
        expect(s.milkLeft).toBe(Math.min(milkCapacity(s), carried.milk + passiveMilkGain(s)));
        expect(s.sugarLeft).toBe(sugarCapacity(s)); // over capacity on arrival: clamped, never more
        expect(s.sugarLeft).toBeLessThan(carried.sugar);
      });

      it('continues cup by cup exactly as 0.22.0 itself went on to brew', () => {
        const { game, readings } = continueFrom(createGame, saved, release.continuations[name].length);
        expect(readings).toEqual(release.continuations[name]);
        expect(game.state.mode).toBe(mode);
      });

      it('keeps its mode, Auto Steam rule and record book through storage, a new save and a reload', () => {
        const storage = memoryStorage({ [POT_KEY]: JSON.stringify(saved) });
        let progress = createLocalProgress(storage);
        expect(progress.status.pot).toBe('');
        expect(progress.potInfo).toMatchObject({ round: saved.state.round, mode, score: saved.state.score });
        const sessions = createSessions(createGame({ seed: 1 }), progress);
        expect(sessions.continuePot()).toBe(true);
        const game = sessions.game;
        expect(game.setAutoSteam(true)).toBe(mode === 'chill');
        game.setAutoSteam(autoSteam);
        // Migration happened in memory only; the release's save stays until a new one replaces it.
        expect(JSON.parse(storage.getItem(POT_KEY))).toEqual(saved);
        leave(game);
        killLast(game);
        for (const event of game.drainEvents()) sessions.handle(event);
        const stored = JSON.parse(storage.getItem(POT_KEY));
        expect(stored).toMatchObject({ schemaVersion: POT_SCHEMA_VERSION, state: { mode, round: saved.state.round + 1 } });
        expect(validateCheckpoint(stored)).toBe(true);
        progress = createLocalProgress(storage);
        expect(progress.modeRecords.modes[mode]).toMatchObject({ cups: 1, plays: 0, bestRound: saved.state.round + 1 });
        expect(progress.modeRecords.modes[mode === 'chill' ? 'arcade' : 'chill'].cups).toBe(0);
        const reloaded = createGame({ checkpoint: progress.pot });
        expect(reloaded.state).toMatchObject({ phase: 'reading', mode, autoSteam, round: saved.state.round + 1 });
      });
    });
  }
});
